{"code": "import os
import subprocess

# 检查系统类型
system = os.uname().sysname
print(f"系统类型: {system}")

# 根据系统安装SSH客户端
if system == "Linux":
    # 尝试安装openssh-client
    try:
        result = subprocess.run(
            ['apt-get', 'update'],
            capture_output=True,
            text=True,
            timeout=60
        )
        print("更新软件源完成")

        result = subprocess.run(
            ['apt-get', 'install', '-y', 'openssh-client'],
            capture_output=True,
            text=True,
            timeout=120
        )

        if result.returncode == 0:
            print("✅ SSH客户端安装成功!")
        else:
            print(f"❌ 安装失败: {result.stderr}")

    except subprocess.TimeoutExpired:
        print("❌ 安装超时")
    except Exception as e:
        print(f"❌ 安装出错: {e}")

elif system == "Darwin":  # macOS
    try:
        result = subprocess.run(
            ['brew', 'install', 'openssh'],
            capture_output=True,
            text=True
        )
        if result.returncode == 0:
            print("✅ SSH客户端安装成功!")
        else:
            print(f"❌ 安装失败: {result.stderr}")
    except Exception as e:
        print(f"❌ 安装出错: {e}")

else:
    print(f"❌ 不支持的系统: {system}")
"}

